#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Choose a tile size for the SPD initialization GEMM; this is a tuning knob.
static constexpr int INIT_TILE = 32;

// Initialize matrix A as in the original Polybench C code.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // A is laid out as A(j, i) == A[i][j] from the C code.
    Var i("i"), j("j");

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // ------------------------------------------------------------------
    // 1) Build the same lower-triangular matrix with diagonal 1
    //    as in the original init_array().
    //
    // C code:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping to Halide: A(j, i) corresponds to A[i][j].
    // ------------------------------------------------------------------
    Func init_tri("init_tri");

    Expr val = cast<num_t>(-(j % n));
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly set the diagonal to 1 (update definition).
    init_tri(i, i) = cast<num_t>(1);

    // Schedule for good locality and vectorization:
    //  - i (the row index) is parallelized
    //  - j (the column index, contiguous in memory) is vectorized
    init_tri
        .compute_root()
        .vectorize(j, vec_width)
        .parallel(i);

    // Realize into the provided buffer A.
    init_tri.realize(A);

    // ------------------------------------------------------------------
    // 2) Make the matrix positive semi-definite:
    //
    // C code:
    // int r, s, t;
    // B[r][s] = 0;
    // for (t = 0; t < n; ++t)
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s)
    //       B[r][s] += A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    //
    // This is B = A * A^T, where A is n x n lower-triangular.
    //
    // Mapping: A[i][t] -> A_param(t, i); B[r][s] -> B_func(s, r).
    // ------------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(0);
    // A[r][t] -> A_param(t, r);  A[s][t] -> A_param(t, s)
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule the GEMM:
    //  - Tile the (s,r) space for cache locality.
    //  - Vectorize across s (contiguous).
    //  - Parallelize outer tiles over r.
    Var ro("ro"), so("so"), ri("ri"), si("si");
    B_func
        .compute_root()
        .tile(s, r, so, ro, si, ri, INIT_TILE, INIT_TILE)
        .vectorize(si, vec_width)
        .parallel(ro);

    // For the reduction update, keep the same tile shape and
    // vectorize across s (the innermost pure dimension).
    B_func.update()
        .reorder(s, r, t)
        .vectorize(s, vec_width)
        .parallel(r);

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A (this is O(n^2) vs the O(n^3) GEMM above,
    // so it's not the bottleneck).
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code.
    init_array(n, A);

    // ------------------------------------------------------------------
    // Build Halide pipelines for the inner products used in the
    // Cholesky factorization. Cholesky has loop-carried dependencies
    // across (i, j), so we keep the outer i,j loops on the host,
    // and use Halide Funcs to compute the k-summations efficiently.
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // We create two small Halide pipelines:
    //
    //   offdiag_sum(i, j) = sum_{k=0..j-1} A(i,k) * A(j,k)
    //   diag_new(i)       = sqrt( A(i,i) - sum_{k=0..i-1} A(i,k)^2 )
    //
    // The host code uses these to update A(j,i) and A(i,i) in place.
    // ------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // ImageParam that views the current contents of A.
    ImageParam A_param(type_of<num_t>(), 2, "A_param_chol");
    A_param.set(A);

    // Scalar parameters for the current i and j.
    Param<int> i_param("i_param"), j_param("j_param");

    // 1) Off-diagonal inner product: sum_{k=0..j-1} A[i][k] * A[j][k]
    //    which maps to sum_{k=0..j-1} A_param(k, i_param) * A_param(k, j_param).
    Func offdiag_sum("offdiag_sum");
    RDom k_off(0, j_param, "k_off");

    offdiag_sum() = cast<num_t>(0);
    offdiag_sum() += A_param(k_off, i_param) * A_param(k_off, j_param);

    // Vectorize across the reduction variable k when possible.
    offdiag_sum.compute_root();
    offdiag_sum.update().vectorize(k_off, vec_width);

    // 2) Diagonal update:
    //    A[i][i] = sqrt( A[i][i] - sum_{k=0..i-1} A[i][k]^2 )
    //    which maps to:
    //    diag_new() = sqrt( A_param(i_param, i_param) -
    //                       sum_{k=0..i_param-1} A_param(k, i_param)^2 ).
    Func diag_new("diag_new");
    RDom k_diag(0, i_param, "k_diag");

    diag_new() = A_param(i_param, i_param);
    diag_new() -= A_param(k_diag, i_param) * A_param(k_diag, i_param);
    diag_new() = Halide::sqrt(diag_new());

    diag_new.compute_root();
    diag_new.update(0).vectorize(k_diag, vec_width);
    // The sqrt update (update(1)) is scalar; no extra schedule needed.

    // JIT-compile the small kernels once, ahead of timing.
    offdiag_sum.compile_jit(target);
    diag_new.compile_jit(target);

    // ------------------------------------------------------------------
    // Time the Cholesky factorization kernel (host-driven outer loops,
    // Halide-driven inner products).
    // ------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // Off-diagonal elements in row i.
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute sum_{k=0..j-1} A[i][k] * A[j][k] using Halide.
            Halide::Buffer<num_t> sum_buf = offdiag_sum.realize();
            num_t sum_val = sum_buf();

            // A[i][j] = (A[i][j] - sum) / A[j][j];
            // Mapping A[i][j] -> A(j, i), A[j][j] -> A(j, j).
            A(j, i) = (A(j, i) - sum_val) / A(j, j);
        }

        // Diagonal element: use Halide to do the inner-product and sqrt.
        Halide::Buffer<num_t> diag_buf = diag_new.realize();
        num_t diag_val = diag_buf();
        A(i, i) = diag_val;
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
