#include <algorithm>
#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -------------------------------------------------------------------------------------------------
// Matrix initialization (Polybench-style) using Halide
// -------------------------------------------------------------------------------------------------
//
// We construct the same SPD matrix as the original C Polybench cholesky:
//
// 1) Build a lower-triangular matrix L with unit diagonal:
//      for (i = 0; i < n; i++) {
//        for (j = 0; j <= i; j++)
//          A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
//        for (j = i+1; j < n; j++)
//          A[i][j] = 0;
//        A[i][i] = 1;
//      }
//
//    In this code we follow the convention A(j, i) == A[i][j].
//
// 2) Make it positive semi-definite via B = A * A^T, then copy B back into A:
//
//      B[r][s] = 0;
//      for (t = 0; t < n; ++t)
//        for (r = 0; r < n; ++r)
//          for (s = 0; s < n; ++s)
//            B[r][s] += A[r][t] * A[s][t];
//      A[r][s] = B[r][s];
//
//    This is exactly B = L * L^T, where L is the lower-triangular matrix above.
//
// Here we fuse both steps into a single Halide pipeline:
//
//   L(j, i) = lower-triangular initializer (not materialized as a separate buffer)
//   A_psd(s, r) = sum_t L(t, r) * L(t, s)   (SPD matrix)
//
// and realize A_psd directly into the provided buffer A.
//
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");
    Var r("r"), s("s");

    // Lower-triangular initializer L(j, i) corresponding to A[i][j] in C.
    Func L("L");

    // val = (DATA_TYPE)(-j % n) / n + 1;
    Expr val = cast<num_t>(-(j % n));
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Below the diagonal (including) use 'val', above is 0.
    L(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly enforce unit diagonal: A[i][i] = 1.
    // (This mirrors the final 'A[i][i] = 1;' in the C code.)
    L(i, i) = cast<num_t>(1);

    // Now build A_psd = L * L^T, i.e., A_psd[r][s] = sum_t L[r][t] * L[s][t].
    // In our coordinate convention:
    //   A_psd(s, r) == B[r][s] == sum_t L(t, r) * L(t, s).
    RDom t(0, n, "t");
    Func A_psd("A_psd");
    A_psd(s, r) = cast<num_t>(0);
    A_psd(s, r) += L(t, r) * L(t, s);

    // ----------------------------------------------------------------------------
    // Schedule for A_psd:
    //
    //  - Compute at root.
    //  - Parallelize over the slow y-dimension (r).
    //  - Vectorize along the contiguous x-dimension (s).
    // ----------------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    A_psd
        .compute_root()
        .parallel(r)
        .vectorize(s, vec_width);

    // Realize directly into the user-provided buffer A.
    A_psd.realize(A);
}

// -------------------------------------------------------------------------------------------------
// Halide kernels for the Cholesky factorization inner products
// -------------------------------------------------------------------------------------------------
//
// The main Cholesky algorithm has loop-carried dependencies along 'i' and 'j':
//
//   for (i = 0; i < N; i++) {
//     // Off-diagonal: j < i
//     for (j = 0; j < i; j++) {
//       for (k = 0; k < j; k++)
//         A[i][j] -= A[i][k] * A[j][k];
//       A[i][j] /= A[j][j];
//     }
//     // Diagonal
//     for (k = 0; k < i; k++)
//       A[i][i] -= A[i][k] * A[i][k];
//     A[i][i] = sqrt(A[i][i]);
//   }
//
// Because each A[i][j] depends on earlier entries in the same row (A[i][k], k<j),
// we cannot express the full algorithm as a single pure Halide reduction without
// violating Halide's reduction rules.
//
// Instead, we follow the recommended pattern for algorithms with loop-carried
// dependencies: keep the outer loops (over i and j) in C++, and factor the
// inner dot-products (over k) into Halide reductions operating on an ImageParam
// that represents the current matrix state. This keeps the math intensive
// inner loops in optimized Halide code, while preserving the required
// sequential dependencies at the C++ level.
//
struct CholeskyKernels {
    // Matrix A as a Halide input. Uses the same layout as the Buffer:
    //   A_img(j, i) == A[i][j] from the Polybench code.
    ImageParam A_img;

    // Parameters for the current row/column indices.
    Param<int> i_param;  // current row  i
    Param<int> j_param;  // current column j (for off-diagonal)

    // offdiag_sum()   = sum_{k=0}^{j-1} A[i][k] * A[j][k]
    // diag_val()      = A[i][i] - sum_{k=0}^{i-1} A[i][k] * A[i][k]
    Func offdiag_sum;
    Func diag_val;

    Target target;
    int vec_width;
    bool compiled;

    CholeskyKernels()
        : A_img(type_of<num_t>(), 2, "A_img"),
          i_param("i_param"),
          j_param("j_param"),
          offdiag_sum("offdiag_sum"),
          diag_val("diag_val"),
          target(get_host_target()),
          vec_width(std::max(1, target.natural_vector_size(type_of<num_t>()))),
          compiled(false) {

        // --------------------------------------------------------------------
        // Off-diagonal inner product:
        //
        //   sum_{k=0}^{j-1} A[i][k] * A[j][k]
        //
        // Mapping to our layout A(j, i) == A[i][j]:
        //   A[i][k] -> A_img(k, i_param)
        //   A[j][k] -> A_img(k, j_param)
        // --------------------------------------------------------------------
        {
            RDom k(0, j_param, "k");
            offdiag_sum() = cast<num_t>(0);
            offdiag_sum() += A_img(k, i_param) * A_img(k, j_param);

            // Compute as a scalar reduction at root, vectorizing the reduction
            // over k where possible.
            offdiag_sum
                .compute_root();
            offdiag_sum
                .update()
                .vectorize(k, vec_width);
        }

        // --------------------------------------------------------------------
        // Diagonal update value:
        //
        //   A[i][i] -= sum_{k=0}^{i-1} A[i][k] * A[i][k]
        //
        // We compute:
        //   diag_val() = A[i][i] - sum_{k=0}^{i-1} A[i][k]^2
        // and then take the square root on the host.
        //
        // Mapping:
        //   A[i][i] -> A_img(i_param, i_param)
        //   A[i][k] -> A_img(k, i_param)
        // --------------------------------------------------------------------
        {
            RDom k2(0, i_param, "k2");
            diag_val() = A_img(i_param, i_param);
            diag_val() -= A_img(k2, i_param) * A_img(k2, i_param);

            diag_val
                .compute_root();
            diag_val
                .update()
                .vectorize(k2, vec_width);
        }
    }

    // Ensure the JIT compilation is done once, before we start timing.
    void compile() {
        if (!compiled) {
            offdiag_sum.compile_jit(target);
            diag_val.compile_jit(target);
            compiled = true;
        }
    }

    // Compute sum_{k=0}^{j-1} A[i][k] * A[j][k] using Halide.
    num_t compute_offdiag(Halide::Buffer<num_t, 2> &A, int i, int j) {
        A_img.set(A);
        i_param.set(i);
        j_param.set(j);

        // offdiag_sum is a 0-D (scalar) Func. Realizing it produces a
        // 0-D Buffer, whose value we read via operator().
        Halide::Buffer<num_t> sum_buf = offdiag_sum.realize();
        return sum_buf();
    }

    // Compute A[i][i] - sum_{k=0}^{i-1} A[i][k]^2 using Halide.
    num_t compute_diag(Halide::Buffer<num_t, 2> &A, int i) {
        A_img.set(A);
        i_param.set(i);

        Halide::Buffer<num_t> diag_buf = diag_val.realize();
        return diag_buf();
    }
};

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code, but using an
    // optimized Halide pipeline for the SPD construction.
    init_array(n, A);

    // Build and JIT-compile the Halide kernels for the inner products
    // before starting the timed region, so that compilation overhead
    // is not included in the performance measurement.
    CholeskyKernels chol_kernels;
    chol_kernels.compile();

    // Time the Cholesky factorization kernel (host-driven outer loops,
    // Halide-accelerated inner products).
    auto start = std::chrono::high_resolution_clock::now();

    // Main computational kernel:
    //
    // Original C (with A[i][j] layout):
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    for (int i = 0; i < n; i++) {
        // Off-diagonal elements in row i: j < i.
        for (int j = 0; j < i; j++) {
            // Compute the inner product sum_{k=0}^{j-1} A[i][k] * A[j][k]
            // using the Halide reduction.
            num_t correction = (j > 0)
                                   ? chol_kernels.compute_offdiag(A, i, j)
                                   : static_cast<num_t>(0);

            // Apply the correction and divide by A[j][j].
            // This is algebraically equivalent to the original nested k-loop.
            A(j, i) = (A(j, i) - correction) / A(j, j);
        }

        // Diagonal element update:
        //
        // Original code:
        //   for (k = 0; k < i; k++)
        //     A[i][i] -= A[i][k] * A[i][k];
        //
        // We compute:
        //   diag_val = A[i][i] - sum_{k=0}^{i-1} A[i][k]^2
        // via Halide, then take the square root here.
        num_t diag_val = chol_kernels.compute_diag(A, i);
        A(i, i) = static_cast<num_t>(
            std::sqrt(static_cast<double>(diag_val)));
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
