            .vectorize(j, vec);
    }

    // Realize into the provided buffer A.
    init_tri.realize(A);

    // Now make the matrix positive semi-definite:
    //
    // C code:
    // int r, s, t;
    // B[r][s] = 0;
    // for (t = 0; t < n; ++t)
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s)
    //       B[r][s] += A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    //
    // This is B = A * A^T where A is n x n lower-triangular.

    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    Expr zero = cast<num_t>(Expr(0));
    // A[r][t] -> A_param(t, r);  A[s][t] -> A_param(t, s)
    B_func(s, r) = zero;
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule for B = A * A^T:
    //  - compute_root: produce entire B in one pass
    //  - parallelize across rows 'r'
    //  - vectorize across columns 's'
    {
        Target target = get_host_target();
        int vec = target.natural_vector_size(type_of<num_t>());
        if (vec < 1) vec = 1;

        // Pure definition: initialize B
        B_func
            .compute_root()
            .parallel(r)
            .vectorize(s, vec);

        // Reduction update: accumulate along t
        B_func.update()
            .reorder(t, s, r)  // inner to outer: t, s, r
            .parallel(r)
            .vectorize(s, vec);
    }

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A (keep layout A(j, i) == A[i][j]).
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code (using Halide).
    init_array(n, A);

    // ------------------------------------------------------------------
    // Set up Halide pipelines for the Cholesky factorization kernel.
    //
    // The Cholesky algorithm is inherently sequential in (i, j), but
    // the inner sums over k are reductions that we can implement as
    // small Halide pipelines. We:
    //   - Keep the outer i and j loops in C++.
    //   - Use Halide Funcs to compute:
    //         sum_{k=0}^{j-1} A[i][k] * A[j][k]
    //         sum_{k=0}^{i-1} A[i][k] * A[i][k]
    //   - Bind the current matrix A via ImageParam so that each sum
    //     sees the up-to-date factor as we overwrite A in-place.
    // ------------------------------------------------------------------

    Target target = get_host_target();

    // ImageParam exposing the current matrix A to Halide pipelines.
    ImageParam A_param_chol(type_of<num_t>(), 2, "A_param_chol");
    A_param_chol.set(A);

    // Scalar parameters for dynamic problem size and loop indices.
    Param<int> N_param("N_param");
    Param<int> i_param("i_param");
    Param<int> j_param("j_param");
    N_param.set(n);

    Expr zero = cast<num_t>(Expr(0));

    // Off-diagonal inner product:
    //   sum_{k=0}^{j-1} A[i][k] * A[j][k]
    // Mapping with A(j, i) == A[i][j]:
    //   A[i][k] -> A_param_chol(k, i)
    //   A[j][k] -> A_param_chol(k, j)
    //
    // We implement this as a 0-D Func that returns a single scalar.
    RDom k_off(0, N_param, "k_off");
    Func offdiag_sum("offdiag_sum");
    offdiag_sum() = zero;
    offdiag_sum() += select(k_off < j_param,
                            A_param_chol(k_off, i_param) * A_param_chol(k_off, j_param),
                            zero);

    // Diagonal accumulation:
    //   sum_{k=0}^{i-1} A[i][k] * A[i][k]
    // Mapping:
    //   A[i][k] -> A_param_chol(k, i)
    RDom k_diag(0, N_param, "k_diag");
    Func diag_sum("diag_sum");
    diag_sum() = zero;
    diag_sum() += select(k_diag < i_param,
                         A_param_chol(k_diag, i_param) * A_param_chol(k_diag, i_param),
                         zero);

    // Schedules for the reduction Funcs:
    // These are 0-D Funcs with a 1-D reduction domain; we vectorize
    // along the reduction variable for better throughput.
    {
        int vec = target.natural_vector_size(type_of<num_t>());
        if (vec < 1) vec = 1;

        // It's safe to leave the pure definitions at root;
        // we just vectorize the update (reduction) along the RDom.
        {
            RVar ko = k_off[0];
            offdiag_sum.update().vectorize(ko, vec);
        }

        {
            RVar kd = k_diag[0];
            diag_sum.update().vectorize(kd, vec);
        }
    }

    // Compile the small pipelines ahead-of-time relative to the timed region,
    // so that JIT compilation cost is not included in the performance timing.
    offdiag_sum.compile_jit(target);
    diag_sum.compile_jit(target);

    // ------------------------------------------------------------------
    // Time the Cholesky factorization kernel.
    // ------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Main computational kernel translated directly, operating on the Buffer.
    //
    // Original C:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // We keep the outer loops over i and j in C++, but replace the
    // inner reductions over k with Halide reductions (offdiag_sum,
    // diag_sum) for better locality and vectorization in k.
    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // Off-diagonal elements in row i (A(j, i) with j < i).
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute sum_{k=0}^{j-1} A[i][k] * A[j][k] using Halide.
            Halide::Buffer<num_t> sum_buf = offdiag_sum.realize();
            num_t s = sum_buf();

            A(j, i) -= s;
            A(j, i) /= A(j, j);
        }

        // Diagonal element A(i, i).
        if (i > 0) {
            // Compute sum_{k=0}^{i-1} A[i][k]^2 using Halide.
            Halide::Buffer<num_t> d_buf = diag_sum.realize();
            num_t d = d_buf();
            A(i, i) -= d;
        }
        A(i, i) = static_cast<num_t>(std::sqrt(static_cast<double>(A(i, i))));
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
