    // Note: we cast the integer expressions to Expr explicitly, then to num_t.
    Expr j_mod = j % n;
    Expr val   = cast<num_t>(-j_mod);
    val        = val / cast<num_t>(Expr(n)) + cast<num_t>(Expr(1));

    // Lower-triangular including diagonal -> 'val', above-diagonal -> 0.
    Expr base = select(j <= i, val, cast<num_t>(Expr(0)));
    init_tri(j, i) = base;

