    //   across tiles of rows.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var io("io"), ii("ii"), jo("jo"), ji("ji");

    init_tri
        .tile(j, i, jo, io, ji, ii, vec_width * 4, INIT_TRI_TILE_I)
        .vectorize(ji, vec_width)
        .parallel(io);

    // Realize into the provided buffer A.
