    //  - tile over (s, r) for better cache use,
    //  - vectorize over s (contiguous dimension),
    //  - parallelize across tiles of r.
    Var ro("ro"), so("so"), ri("ri"), si("si");

    B_func.compute_root();

    // Update definition schedule (the reduction).
    B_func.update()
        .tile(s, r, so, ro, si, ri, SPD_TILE_S, SPD_TILE_R)
        .reorder(t, si, ri, so, ro)
        .vectorize(si, vec_width)
        .parallel(ro);

    // Realize B into its own buffer (we must not overwrite A while reading it).
    Halide::Buffer<num_t, 2> B(n, n, "B_buffer");
    B_func.realize(B);

    /**********************************************************************
     * 3) Copy B back into A using a small Halide pipeline.
     *
     * This replaces the manual nested for-loops:
     *   for (r = 0; r < n; ++r)
     *     for (s = 0; s < n; ++s)
     *       A[s][r] = B[s][r];
     **********************************************************************/
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    B_param.set(B);

    Func A_copy("A_copy");
    A_copy(s, r) = B_param(s, r);

    // Schedule: parallelize over rows, vectorize over contiguous columns.
    A_copy
        .compute_root()
        .parallel(r)
        .vectorize(s, vec_width);

    A_copy.realize(A);
}

