    Param<num_t> diag_param("diag_param");

    // ------------------------
    // Diagonal computation:
    // diag_f(idx) = sqrt( A(j,j) - sum_{k=0..j-1} A(k,j)^2 )
    // ------------------------
    Var idx("idx");
    RDom r_diag(0, j_param, "r_diag");

    Func diag_f("chol_diag");
    {
        Expr diag_sum = sum(A_param_chol(r_diag, j_param) *
                            A_param_chol(r_diag, j_param));
        Expr diag_expr = sqrt(A_param_chol(j_param, j_param) - diag_sum);
        // Make it 1D to get a scalar in a 1-element buffer.
        diag_f(idx) = diag_expr;
    }

    // ------------------------
    // Column computation:
    // col_f(i) = (A(j,i) - sum_{k=0..j-1} A(k,i) * A(k,j)) / diag_param
    // ------------------------
    Var i_var("i_var");
    RDom r_col(0, j_param, "r_col");

    Func col_f("chol_col");
    {
        Expr col_sum = sum(A_param_chol(r_col, i_var) *
                           A_param_chol(r_col, j_param));
        Expr col_expr = (A_param_chol(j_param, i_var) - col_sum) / diag_param;
        col_f(i_var) = col_expr;
    }

    // Schedule: both Funcs are small 1D pipelines. We parallelize and
    // vectorize along the i dimension for col_f to get good throughput.
    diag_f
        .compute_root()
        .vectorize(idx, vec_width);

    col_f
        .compute_root()
        .parallel(i_var)
        .vectorize(i_var, vec_width);

    // JIT-compile once, outside the timed region.
    diag_f.compile_jit(target);
    col_f.compile_jit(target);

    // ------------------------------------------------------------------
    // Time the Cholesky factorization kernel.
    // ------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Temporary buffers reused for each column step.
    Halide::Buffer<num_t> diag_buf(1);
    Halide::Buffer<num_t> col_buf(n);

    for (int j = 0; j < n; j++) {
        j_param.set(j);

        // 1) Compute the updated diagonal A(j, j) using Halide.
        diag_f.realize(diag_buf);
        num_t diag_val = diag_buf(0);
        // Write back into A.
        A(j, j) = diag_val;

        // 2) Compute the updated column entries below the diagonal.
        diag_param.set(diag_val);  // denominator for the column update.
        col_f.realize(col_buf);

        // Copy updated column j entries A(j, i) for i > j.
        for (int i = j + 1; i < n; i++) {
            A(j, i) = col_buf(i);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
